// browser_network_requests 实现：首次调用按需开启 CDP Network 监听，之后读环形缓冲
#include "browser_network_requests.h" // 自身声明
#include "server/cdp_client.h" // network 缓冲
#include "browser_tool/tool_helpers.h" // Reply/ReplyText
#include "utils/json_util.h" // 参数读取/序列化
void BrowserNetworkRequestsTool::Run(const ToolRequest& req) { bool include_static = false; ArgGetBool(req.args, "includeStatic", include_static); std::string filter; ArgGetString(req.args, "filter", filter); if (!req.cdp->network_enabled()) { req.cdp->EnableNetwork(); CefRefPtr<CefDictionaryValue> data = MakeDict(); data->SetBool("enabled", true); data->SetString("note", "网络监听已开启，请稍后再次调用 browser_network_requests 获取记录"); tool::Reply(req.id, data); return; } CefRefPtr<CefListValue> list = MakeList(); for (const NetworkEntry& entry : req.cdp->network()) { if (!include_static && (entry.type == "Script" || entry.type == "Image" || entry.type == "Font" || entry.type == "Media" || entry.type == "Stylesheet")) continue; if (!filter.empty() && entry.url.find(filter) == std::string::npos && std::to_string(entry.status) != filter) continue; CefRefPtr<CefDictionaryValue> item = MakeDict(); item->SetString("url", entry.url); item->SetString("method", entry.method); item->SetString("type", entry.type); item->SetInt("status", entry.status); item->SetDouble("ms", entry.end_ts > entry.start_ts ? (entry.end_ts - entry.start_ts) * 1000.0 : 0.0); if (!entry.error.empty()) item->SetString("error", entry.error); ListAddDict(list, item); } tool::ReplyText(req.id, WriteJsonList(list)); } // 首次开启监听提示稍后再查；默认滤掉静态资源，支持按 URL 子串或状态码过滤，回 JSON 列表
